/**
 * PWA static assets for the fleet's HTML surfaces (run receipts + transcript
 * viewer): the web app manifest and the home-screen icons.
 *
 * WHY THIS EXISTS (docs/FLEET-SESSION-TRANSCRIPTS.md, Phase 5): the RFC's iOS
 * answer is "make the web viewer fully responsive and PWA-installable first" —
 * a SwiftUI reader stays a demand-driven later step. These routes are the
 * installable half: Add to Home Screen on iOS reads the apple-touch-icon link,
 * Android/desktop read the manifest.
 *
 * AUTHZ: none, deliberately. Everything here is public app metadata — a name,
 * two colors, three flat-color icons. No run data, no capability tokens, no
 * per-account anything; the pages themselves keep their uniform-404 posture.
 * That is also why these responses are cacheable while every fleet page is
 * no-store.
 */

// Flat-color "pd" tiles (cobalt slab, cream wordmark, lime keel stripe — the
// site's linework palette). Palette-mode PNGs, ~1–2KB each; regenerate by
// redrawing at 180/192/512 with the same three colors if the brand shifts.
const APPLE_TOUCH_ICON_B64 =
  '';
const ICON_192_B64 =
  '';
const ICON_512_B64 =
  '';

function pngResponse(b64: string): Response {
  const raw = atob(b64);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i += 1) bytes[i] = raw.charCodeAt(i);
  return new Response(bytes, {
    status: 200,
    headers: {
      'Content-Type': 'image/png',
      // Public static asset — safe to cache, unlike the no-store fleet pages.
      'Cache-Control': 'public, max-age=86400',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}

export function handleFleetAppleTouchIcon(): Response {
  return pngResponse(APPLE_TOUCH_ICON_B64);
}

export function handleFleetIcon192(): Response {
  return pngResponse(ICON_192_B64);
}

export function handleFleetIcon512(): Response {
  return pngResponse(ICON_512_B64);
}

/**
 * The web app manifest. start_url is the operator's runs index — the one
 * fleet surface with a stable URL (run receipts are per-run capability URLs,
 * so pinning THE app means pinning the index; signed-out it lands on /login,
 * which is the honest behavior for an authenticated surface). scope stays "/"
 * so opened run receipts and transcript viewers remain inside the installed
 * app instead of bouncing to the browser.
 */
export function handleFleetManifest(): Response {
  const manifest = {
    name: 'Port Daddy Fleet',
    short_name: 'PD Fleet',
    description: 'Fleet run receipts and raw ship session transcripts.',
    start_url: '/account/runs',
    scope: '/',
    display: 'standalone',
    background_color: '#f2eee6',
    theme_color: '#f2eee6',
    icons: [
      { src: '/fleet/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: '/fleet/icon-512.png', sizes: '512x512', type: 'image/png' },
    ],
  };
  return new Response(JSON.stringify(manifest, null, 2), {
    status: 200,
    headers: {
      'Content-Type': 'application/manifest+json',
      'Cache-Control': 'public, max-age=86400',
      'X-Content-Type-Options': 'nosniff',
    },
  });
}
